template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{60} \def\showcenter{1} \def\showradius{1} \def\showchord{0} \def\showsector{0} \def\showsegment{0}
% 视觉归一化：把圆直径缩放到 6（单位由 coordScale 决定）。
% A、B 关于正 x 轴对称，中心角 anglea 平分在 x 轴两侧，图形居中稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
\pgfmathsetmacro{\halfa}{\anglea/2}
\pgfmathsetmacro{\Ax}{\radius*cos(\halfa)}
\pgfmathsetmacro{\Ay}{-\radius*sin(\halfa)}
\pgfmathsetmacro{\Bx}{\radius*cos(\halfa)}
\pgfmathsetmacro{\By}{\radius*sin(\halfa)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  % 扇形 AOB 填充（两条半径 + 弧围成）
  \ifnum\showsector>0
    \fill[green!12] (O) -- (A) arc[start angle=-\halfa, end angle=\halfa, radius=\radius] -- cycle;
  \fi
  % 弓形填充（弦 AB 与弧 AB 围成，先画避免覆盖弦）
  \ifnum\showsegment>0
    \fill[green!12] (A) -- (B) arc[start angle=\halfa, end angle=-\halfa, radius=\radius] -- cycle;
  \fi
  % 两条半径
  \ifnum\showradius>0
    \draw[thick] (O) -- (A);
    \draw[thick] (O) -- (B);
  \fi
  % 弦 AB
  \ifnum\showchord>0
    \draw[thick] (A) -- (B);
  \fi
  % 弧 AB（小弧，恒画作为扇形/弓形边界）
  \draw[thick] (A) arc[start angle=-\halfa, end angle=\halfa, radius=\radius];
  % 端点与圆心
  \fill (A) circle [radius=1.6pt];
  \fill (B) circle [radius=1.6pt];
  \node[below=3pt] at (A) {$A$};
  \node[above=3pt] at (B) {$B$};
  \ifnum\showcenter>0
    \fill (O) circle [radius=1.6pt];
    \node[below left=3pt] at (O) {$O$};
  \fi
  % 圆心角角弧（两半径之间，需半径存在）
  \ifnum\showcenter>0
    \ifnum\showradius>0
      \pgfmathsetmacro{\arcr}{min(0.45, \radius*0.18)}
      \draw[thick] ({\arcr*cos(\halfa)},{\arcr*sin(\halfa)}) arc[start angle=\halfa, end angle=-\halfa, radius=\arcr];
    \fi
  \fi
\end{tikzpicture}
